    65→### 1.2 Addressables基础配置
    66→
    67→```csharp
    68→using UnityEngine;
    69→using UnityEngine.AddressableAssets;
    70→using UnityEngine.ResourceManagement.AsyncOperations;
    71→using System.Collections.Generic;
    72→
    73→/// <summary>
    74→/// Addressables资源管理器
    75→/// </summary>
    76→public class AddressablesManager : MonoBehaviour
    77→{
    78→    private static AddressablesManager instance;
    79→    public static AddressablesManager Instance => instance;
    80→
    81→    // 缓存已加载的资源
    82→    private Dictionary<string, AsyncOperationHandle> loadedAssets = new Dictionary<string, AsyncOperationHandle>();
    83→    private Dictionary<string, int> referenceCounts = new Dictionary<string, int>();
    84→
    85→    private void Awake()
    86→    {
    87→        instance = this;
    88→    }
    89→
    90→    /// <summary>
    91→    /// 同步加载资源（实际上是异步，返回句柄）
    92→    /// </summary>
    93→    public AsyncOperationHandle<T> LoadAssetAsync<T>(string address) where T : Object
    94→    {
    95→        // 检查是否已加载
    96→        if (loadedAssets.TryGetValue(address, out var existingHandle))
    97→        {
    98→            referenceCounts[address]++;
    99→            return existingHandle.Convert<T>();
   100→        }
   101→
   102→        // 加载新资源
   103→        var handle = Addressables.LoadAssetAsync<T>(address);
   104→        loadedAssets[address] = handle;
   105→        referenceCounts[address] = 1;
   106→
   107→        return handle;
   108→    }
   109→
   110→    /// <summary>
   111→    /// 加载并等待完成
   112→    /// </summary>
   113→    public System.Collections.IEnumerator LoadAssetCoroutine<T>(string address, System.Action<T> onComplete) where T : Object
   114→    {
   115→        var handle = LoadAssetAsync<T>(address);
   116→        yield return handle;
   117→
   118→        if (handle.Status == AsyncOperationStatus.Succeeded)
   119→        {
   120→            onComplete?.Invoke(handle.Result);
   121→        }
   122→        else
   123→        {
   124→            Debug.LogError($"Failed to load asset: {address}");
   125→            onComplete?.Invoke(null);
   126→        }
   127→    }
   128→
   129→    /// <summary>
   130→    /// 释放资源
   131→    /// </summary>
   132→    public void ReleaseAsset(string address)
   133→    {
   134→        if (!referenceCounts.ContainsKey(address))
   135→            return;
   136→
   137→        referenceCounts[address]--;
   138→
   139→        if (referenceCounts[address] <= 0)
   140→        {
   141→            if (loadedAssets.TryGetValue(address, out var handle))
   142→            {
   143→                Addressables.Release(handle);
   144→                loadedAssets.Remove(address);
   145→            }
   146→            referenceCounts.Remove(address);
   147→        }
   148→    }
   149→
   150→    /// <summary>
   151→    /// 释放所有资源
   152→    /// </summary>
   153→    public void ReleaseAll()
   154→    {
   155→        foreach (var handle in loadedAssets.Values)
   156→        {
   157→            Addressables.Release(handle);
   158→        }
   159→        loadedAssets.Clear();
   160→        referenceCounts.Clear();
   161→    }
   162→}
   163→```
