   241→### 1.4 资源更新检测
   242→
   243→```csharp
   244→using UnityEngine;
   245→using UnityEngine.AddressableAssets;
   246→using UnityEngine.ResourceManagement.AsyncOperations;
   247→using System.Collections.Generic;
   248→
   249→/// <summary>
   250→/// Addressables更新管理器
   251→/// </summary>
   252→public class AddressablesUpdateManager : MonoBehaviour
   253→{
   254→    [Header("Settings")]
   255→    [SerializeField] private bool checkForUpdatesOnStart = true;
   256→    [SerializeField] private string updateLabel = "Remote";
   257→
   258→    public System.Action<float> OnDownloadProgress;
   259→    public System.Action<bool> OnUpdateComplete;
   260→
   261→    private void Start()
   262→    {
   263→        if (checkForUpdatesOnStart)
   264→        {
   265→            CheckForUpdates();
   266→        }
   267→    }
   268→
   269→    /// <summary>
   270→    /// 检查资源更新
   271→    /// </summary>
   272→    public void CheckForUpdates()
   273→    {
   274→        StartCoroutine(CheckForUpdatesCoroutine());
   275→    }
   276→
   277→    private IEnumerator CheckForUpdatesCoroutine()
   278→    {
   279→        // 初始化Addressables（如果尚未初始化）
   280→        var initOp = Addressables.InitializeAsync();
   281→        yield return initOp;
   282→
   283→        // 检查目录更新
   284→        var checkOp = Addressables.CheckForCatalogUpdates();
   285→        yield return checkOp;
   286→
   287→        if (checkOp.Status == AsyncOperationStatus.Succeeded)
   288→        {
   289→            var catalogs = checkOp.Result;
   290→
   291→            if (catalogs != null && catalogs.Count > 0)
   292→            {
   293→                Debug.Log($"Found {catalogs.Count} catalog updates");
   294→                StartCoroutine(DownloadUpdates(catalogs));
   295→            }
   296→            else
   297→            {
   298→                Debug.Log("No updates available");
   299→                OnUpdateComplete?.Invoke(false);
   300→            }
   301→        }
   302→        else
   303→        {
   304→            Debug.LogError("Failed to check for updates");
   305→            OnUpdateComplete?.Invoke(false);
   306→        }
   307→    }
   308→
   309→    /// <summary>
   310→    /// 下载更新
   311→    /// </summary>
   312→    private IEnumerator DownloadUpdates(List<string> catalogs)
   313→    {
   314→        // 更新目录
   315→        var updateOp = Addressables.UpdateCatalogs(catalogs);
   316→        yield return updateOp;
   317→
   318→        if (updateOp.Status != AsyncOperationStatus.Succeeded)
   319→        {
   320→            Debug.LogError("Failed to update catalogs");
   321→            OnUpdateComplete?.Invoke(false);
   322→            yield break;
   323→        }
   324→
   325→        // 获取下载大小
   326→        var sizeOp = Addressables.GetDownloadSizeAsync(updateLabel);
   327→        yield return sizeOp;
   328→
   329→        long totalSize = sizeOp.Result;
   330→        Debug.Log($"Download size: {totalSize / 1024 / 1024} MB");
   331→
   332→        if (totalSize > 0)
   333→        {
   334→            // 开始下载
   335→            var downloadOp = Addressables.DownloadDependenciesAsync(updateLabel);
   336→
   337→            while (!downloadOp.IsDone)
   338→            {
   339→                float progress = downloadOp.PercentComplete;
   340→                OnDownloadProgress?.Invoke(progress);
   341→                Debug.Log($"Download progress: {progress * 100:F0}%");
   342→                yield return null;
   343→            }
   344→
   345→            if (downloadOp.Status == AsyncOperationStatus.Succeeded)
   346→            {
   347→                Debug.Log("Download complete!");
   348→                OnUpdateComplete?.Invoke(true);
   349→            }
   350→            else
   351→            {
   352→                Debug.LogError("Download failed!");
   353→                OnUpdateComplete?.Invoke(false);
   354→            }
   355→
   356→            Addressables.Release(downloadOp);
   357→        }
   358→        else
   359→        {
   360→            OnUpdateComplete?.Invoke(false);
   361→        }
   362→
   363→        Addressables.Release(sizeOp);
   364→    }
   365→}
   366→```
