   403→### 2.2 版本管理
   404→
   405→```csharp
   406→using UnityEngine;
   407→using System;
   408→
   409→/// <summary>
   410→/// 版本管理器
   411→/// </summary>
   412→public class VersionManager : MonoBehaviour
   413→{
   414→    [Serializable]
   415→    public class VersionInfo
   416→    {
   417→        public string version;
   418→        public string resourceVersion;
   419→        public int codeVersion;
   420→        public string updateUrl;
   421→        public bool forceUpdate;
   422→        public string updateMessage;
   423→    }
   424→
   425→    [Header("Current Version")]
   426→    [SerializeField] private string currentVersion = "1.0.0";
   427→    [SerializeField] private int currentCodeVersion = 1;
   428→
   429→    [Header("Settings")]
   430→    [SerializeField] private string versionCheckUrl = "https://your-server.com/version.json";
   431→
   432→    public VersionInfo LatestVersion { get; private set; }
   433→
   434→    /// <summary>
   435→    /// 检查版本更新
   436→    /// </summary>
   437→    public IEnumerator CheckVersion(System.Action<VersionInfo, bool> onComplete)
   438→    {
   439→        using (UnityEngine.Networking.UnityWebRequest request = UnityEngine.Networking.UnityWebRequest.Get(versionCheckUrl))
   440→        {
   441→            yield return request.SendWebRequest();
   442→
   443→            if (request.result == UnityEngine.Networking.UnityWebRequest.Result.Success)
   444→            {
   445→                try
   446→                {
   447→                    LatestVersion = JsonUtility.FromJson<VersionInfo>(request.downloadHandler.text);
   448→
   449→                    bool needUpdate = CompareVersions(LatestVersion.version, currentVersion) > 0 ||
   450→                                     LatestVersion.codeVersion > currentCodeVersion;
   451→
   452→                    onComplete?.Invoke(LatestVersion, needUpdate);
   453→                }
   454→                catch (Exception e)
   455→                {
   456→                    Debug.LogError($"Failed to parse version info: {e.Message}");
   457→                    onComplete?.Invoke(null, false);
   458→                }
   459→            }
   460→            else
   461→            {
   462→                Debug.LogError($"Version check failed: {request.error}");
   463→                onComplete?.Invoke(null, false);
   464→            }
   465→        }
   466→    }
   467→
   468→    /// <summary>
   469→    /// 比较版本号
   470→    /// </summary>
   471→    private int CompareVersions(string version1, string version2)
   472→    {
   473→        string[] parts1 = version1.Split('.');
   474→        string[] parts2 = version2.Split('.');
   475→
   476→        int maxLength = Mathf.Max(parts1.Length, parts2.Length);
   477→
   478→        for (int i = 0; i < maxLength; i++)
   479→        {
   480→            int v1 = i < parts1.Length ? int.Parse(parts1[i]) : 0;
   481→            int v2 = i < parts2.Length ? int.Parse(parts2[i]) : 0;
   482→
   483→            if (v1 > v2) return 1;
   484→            if (v1 < v2) return -1;
   485→        }
   486→
   487→        return 0;
   488→    }
   489→
   490→    /// <summary>
   491→    /// 打开应用商店
   492→    /// </summary>
   493→    public void OpenAppStore()
   494→    {
   495→#if UNITY_ANDROID
   496→        // 打开Google Play
   497→        Application.OpenURL($"market://details?id={Application.identifier}");
   498→#elif UNITY_IOS
   499→        // 打开App Store
   500→        Application.OpenURL("itms-apps://itunes.apple.com/app/idYOUR_APP_ID");
   501→#endif
   502→    }
   503→}
   504→```
