   506→### 2.3 HybridCLR集成
   507→
   508→```csharp
   509→using UnityEngine;
   510→using System;
   511→using System.Collections;
   512→using System.Collections.Generic;
   513→using System.IO;
   514→using System.Reflection;
   515→
   516→#if ENABLE_HYBRIDCLR
   517→using HybridCLR;
   518→using HybridCLR.Data;
   519→#endif
   520→
   521→/// <summary>
   522→/// HybridCLR热更新管理器
   523→/// </summary>
   524→public class HybridCLRMgr : MonoBehaviour
   525→{
   526→    /*
   527→    ========== HybridCLR简介 ==========
   528→
   529→    HybridCLR是Unity的C#热更新解决方案：
   530→    - 支持全C#热更新
   531→    - 无需学习Lua
   532→    - 支持泛型、反射等特性
   533→    - 性能接近原生
   534→
   535→    ========== 工作流程 ==========
   536→
   537→    1. 将热更新代码编译为DLL
   538→    2. 将DLL打包为Addressables资源
   539→    3. 运行时下载DLL
   540→    4. 加载并执行热更新代码
   541→
   542→    ========== 配置步骤 ==========
   543→
   544→    1. 安装HybridCLR包
   545→    2. 配置热更新程序集
   546→    3. 生成AOT DLL和补充元数据
   547→    4. 打包热更新DLL
   548→    */
   549→
   550→    [Header("Settings")]
   551→    [SerializeField] private bool enableHotUpdate = true;
   552→    [SerializeField] private string hotUpdateDllName = "HotUpdate";
   553→
   554→    /// <summary>
   555→    /// 加载热更新程序集
   556→    /// </summary>
   557→    public IEnumerator LoadHotUpdateAssembly(System.Action<Assembly> onComplete)
   558→    {
   559→        if (!enableHotUpdate)
   560→        {
   561→            onComplete?.Invoke(null);
   562→            yield break;
   563→        }
   564→
   565→#if ENABLE_HYBRIDCLR
   566→        // 加载AOT元数据
   567→        yield return LoadAOTMetadata();
   568→
   569→        // 加载热更新DLL
   570→        var dllPath = Path.Combine(Application.persistentDataPath, "HotUpdate", $"{hotUpdateDllName}.dll");
   571→
   572→        if (File.Exists(dllPath))
   573→        {
   574→            byte[] dllBytes = File.ReadAllBytes(dllPath);
   575→            Assembly hotUpdateAssembly = Assembly.Load(dllBytes);
   576→
   577→            Debug.Log("Hot update assembly loaded successfully");
   578→            onComplete?.Invoke(hotUpdateAssembly);
   579→        }
   580→        else
   581→        {
   582→            // 从Addressables加载
   583→            yield return LoadFromAddressables(onComplete);
   584→        }
   585→#else
   586→        Debug.LogWarning("HybridCLR is not enabled");
   587→        onComplete?.Invoke(null);
   588→#endif
   589→    }
   590→
   591→#if ENABLE_HYBRIDCLR
   592→    private IEnumerator LoadAOTMetadata()
   593→    {
   594→        // 加载AOT补充元数据
   595→        HomologousImageManager imageManager = HomologousImageManager.Instance;
   596→
   597→        string[] aotDlls = new string[]
   598→        {
   599→            "mscorlib",
   600→            "System",
   601→            "System.Core",
   602→            "UnityEngine.CoreModule"
   603→        };
   604→
   605→        foreach (var dllName in aotDlls)
   606→        {
   607→            var handle = UnityEngine.AddressableAssets.Addressables.LoadAssetAsync<TextAsset>($"AOT/{dllName}");
   608→            yield return handle;
   609→
   610→            if (handle.Status == UnityEngine.ResourceManagement.AsyncOperations.AsyncOperationStatus.Succeeded)
   611→            {
   612→                byte[] dllBytes = handle.Result.bytes;
   613→                imageManager.LoadImage(dllBytes);
   614→                Debug.Log($"Loaded AOT metadata: {dllName}");
   615→            }
   616→        }
   617→    }
   618→#endif
   619→
   620→    private IEnumerator LoadFromAddressables(System.Action<Assembly> onComplete)
   621→    {
   622→        var handle = UnityEngine.AddressableAssets.Addressables.LoadAssetAsync<TextAsset>($"HotUpdate/{hotUpdateDllName}.dll.bytes");
   623→        yield return handle;
   624→
   625→        if (handle.Status == UnityEngine.ResourceManagement.AsyncOperations.AsyncOperationStatus.Succeeded)
   626→        {
   627→            byte[] dllBytes = handle.Result.bytes;
   628→            Assembly assembly = Assembly.Load(dllBytes);
   629→            onComplete?.Invoke(assembly);
   630→        }
   631→        else
   632→        {
   633→            Debug.LogError($"Failed to load hot update DLL: {handle.OperationException}");
   634→            onComplete?.Invoke(null);
   635→        }
   636→    }
   637→}
