   771→    /// <summary>
   772→    /// 获取纹理总大小
   773→    /// </summary>
   774→    [MenuItem("Tools/Package/Analyze Textures")]
   775→    public static void AnalyzeTextures()
   776→    {
   777→        var textures = Selection.GetFiltered<Texture2D>(SelectionMode.DeepAssets);
   778→        long totalSize = 0;
   779→
   780→        foreach (var tex in textures)
   781→        {
   782→            var importer = AssetImporter.GetAtPath(AssetDatabase.GetAssetPath(tex)) as TextureImporter;
   783→            if (importer != null)
   784→            {
   785→                long size = EstimateTextureSize(tex, importer);
   786→                totalSize += size;
   787→                Debug.Log($"{tex.name}: {tex.width}x{tex.height} ({importer.GetAutomaticFormat("Android")}) = {size / 1024}KB");
   788→            }
   789→        }
   790→
   791→        Debug.Log($"Total texture size: {totalSize / 1024 / 1024}MB");
   792→    }
   793→
   794→    private static long EstimateTextureSize(Texture2D tex, TextureImporter importer)
   795→    {
   796→        int maxTextureSize = importer.maxTextureSize;
   797→        int actualWidth = Mathf.Min(tex.width, maxTextureSize);
   798→        int actualHeight = Mathf.Min(tex.height, maxTextureSize);
   799→
   800→        // 根据格式估算
   801→        TextureFormat format = importer.GetAutomaticFormat("Android");
   802→        int bytesPerPixel = GetBytesPerPixel(format);
   803→
   804→        long size = (long)actualWidth * actualHeight * bytesPerPixel;
   805→
   806→        if (importer.mipmapEnabled)
   807→            size = (long)(size * 1.33);
   808→
   809→        return size;
   810→    }
   811→
   812→    private static int GetBytesPerPixel(TextureFormat format)
   813→    {
   814→        return format switch
   815→        {
   816→            TextureFormat.ASTC_4x4 => 1,
   817→            TextureFormat.ASTC_6x6 => 1,
   818→            TextureFormat.ASTC_8x8 => 1,
   819→            TextureFormat.ETC_RGB4 => 1,
   820→            TextureFormat.ETC2_RGBA8 => 1,
   821→            TextureFormat.RGBA32 => 4,
   822→            TextureFormat.RGB24 => 3,
   823→            _ => 4
   824→        };
   825→    }
   826→}
