   829→### 3.3 分包加载
   830→
   831→```csharp
   832→using UnityEngine;
   833→using System.Collections.Generic;
   834→
   835→/// <summary>
   836→/// 分包加载管理器
   837→/// </summary>
   838→public class SplitPackageLoader : MonoBehaviour
   839→{
   840→    /*
   841→    ========== 分包策略 ==========
   842→
   843→    首包（必装）：
   844→    ├── 启动场景
   845→    ├── 主菜单UI
   846→    ├── 核心游戏逻辑
   847→    ├── 基础棋子资源
   848→    └── 约50MB
   849→
   850→    资源包（按需下载）：
   851→    ├── 关卡1-10资源
   852→    ├── 关卡11-20资源
   853→    ├── 英雄皮肤包
   854→    ├── 特效包
   855→    └── 每个10-30MB
   856→    */
   857→
   858→    [System.Serializable]
   859→    public class PackageInfo
   860→    {
   861→        public string packageName;
   862→        public string addressLabel;
   863→        public long sizeBytes;
   864→        public bool isDownloaded;
   865→        public bool isRequired;
   866→    }
   867→
   868→    [Header("Packages")]
   869→    [SerializeField] private List<PackageInfo> packages;
   870→
   871→    public System.Action<string, float> OnPackageDownloadProgress;
   872→    public System.Action<string> OnPackageDownloadComplete;
   873→
   874→    /// <summary>
   875→    /// 检查资源包状态
   876→    /// </summary>
   877→    public IEnumerator CheckPackageStatus()
   878→    {
   879→        foreach (var package in packages)
   880→        {
   881→            var handle = UnityEngine.AddressableAssets.Addressables.GetDownloadSizeAsync(package.addressLabel);
   882→            yield return handle;
   883→
   884→            if (handle.Status == UnityEngine.ResourceManagement.AsyncOperations.AsyncOperationStatus.Succeeded)
   885→            {
   886→                package.sizeBytes = handle.Result;
   887→                package.isDownloaded = handle.Result == 0;
   888→            }
   889→
   890→            UnityEngine.AddressableAssets.Addressables.Release(handle);
   891→        }
   892→    }
   893→
   894→    /// <summary>
   895→    /// 下载资源包
   896→    /// </summary>
   897→    public IEnumerator DownloadPackage(string packageName)
   898→    {
   899→        var package = packages.Find(p => p.packageName == packageName);
   900→        if (package == null) yield break;
   901→
   902→        var handle = UnityEngine.AddressableAssets.Addressables.DownloadDependenciesAsync(package.addressLabel);
   903→
   904→        while (!handle.IsDone)
   905→        {
   906→            OnPackageDownloadProgress?.Invoke(packageName, handle.PercentComplete);
   907→            yield return null;
   908→        }
   909→
   910→        if (handle.Status == UnityEngine.ResourceManagement.AsyncOperations.AsyncOperationStatus.Succeeded)
   911→        {
   912→            package.isDownloaded = true;
   913→            OnPackageDownloadComplete?.Invoke(packageName);
   914→        }
   915→
   916→        UnityEngine.AddressableAssets.Addressables.Release(handle);
   917→    }
   918→
   919→    /// <summary>
   920→    /// 获取总下载大小
   921→    /// </summary>
   922→    public long GetTotalDownloadSize()
   923→    {
   924→        long total = 0;
   925→        foreach (var package in packages)
   926→        {
   927→            if (!package.isDownloaded)
   928→                total += package.sizeBytes;
   929→        }
   930→        return total;
   931→    }
   932→}
   933→```
