    27→## 1. URP Volume系统
    28→
    29→**Volume系统**是URP的后处理框架，允许通过Volume组件配置各种后处理效果。
    30→
    31→```
    32→┌─────────────────────────────────────────────────────────────┐
    33→│                     URP Volume 系统                          │
    34→│                                                             │
    35→│   ┌─────────────┐     ┌─────────────┐     ┌─────────────┐   │
    36→│   │   Volume    │────→│    Profile    │────→│   Override  │   │
    37→│   │  (全局配置) │     │   (效果配置)   │     │  (覆盖效果)   │   │
    38→│   └─────────────┘     └─────────────┘     └─────────────┘   │
    39→│         │                  │                    │                │
    40→│         ↓                  ↓                    ↓                │
    41→│   ┌─────────────────────────────────────────────────────────┐   │
    42→│   │              Volume Stack (效果栈)                        │   │
    43→│   │  Bloom → Tonemapping → Vignette → ColorGrading          │   │
    44→│   └─────────────────────────────────────────────────────────┘   │
    45→└─────────────────────────────────────────────────────────────┘
    46→```
    47→
    48→### Volume组件
    49→
    50→```csharp
    51→using UnityEngine.Rendering;
    52→using UnityEngine.Rendering.Universal;
    53→
    54→/// <summary>
    55→/// Volume组件 - 挂载到相机上配置后处理效果
    56→/// </summary>
    57→public class PostProcessVolume : MonoBehaviour
    58→{
    59→    [Header("Volume Settings")]
    60→    [SerializeField] private bool isGlobal = true;
    61→    [SerializeField] private int priority = 0;
    62→
    63→    private Volume volume;
    64→
    65→    private void Awake()
    66→    {
    67→        volume = GetComponent<Volume>();
    68→        if (volume == null)
    69→        {
    70→            volume = gameObject.AddComponent<Volume>();
    71→        }
    72→
    73→        volume.isGlobal = isGlobal;
    74→        volume.priority = priority;
    75→    }
    76→
    77→    private void OnEnable()
    78→    {
    79→        if (isGlobal)
    80→        {
    81→            VolumeManager.instance.Register(volume, priority);
    82→        }
    83→    }
    84→
    85→    private void OnDisable()
    86→    {
    87→        if (isGlobal)
    88→        {
    89→            VolumeManager.instance.Unregister(volume);
    90→        }
    91→    }
    92→}
    93→```
