   177→## 3. 自定义后处理（Renderer Feature）
   178→
   179→通过`ScriptableRendererFeature`实现自定义后处理效果。
   180→
   181→```csharp
   182→using UnityEngine.Rendering;
   183→using UnityEngine.Rendering.Universal;
   184→
   185→/// <summary>
   186→/// 自定义后处理效果
   187→/// </summary>
   188→public class CustomPostProcessFeature : ScriptableRendererFeature
   189→{
   190→    [System.Serializable]
   191→    public class CustomSettings
   192→    {
   193→        public Material material;
   194→        public float intensity = 1.0f;
   195→        public Color tintColor = Color.white;
   196→    }
   197→
   198→    [SerializeField] private CustomSettings settings = new CustomSettings();
   199→
   200→    private CustomPostProcessPass pass;
   201→
   202→    public override void Create()
   203→    {
   204→        pass = new CustomPostProcessPass(settings);
   205→    }
   206→
   207→    public override void AddRenderPasses(ScriptableRenderer renderer, ref RenderingData renderingData)
   208→    {
   209→        renderer.EnqueuePass(pass);
   210→    }
   211→
   212→    private class CustomPostProcessPass : ScriptableRenderPass
   213→    {
   214→        private CustomSettings settings;
   215→        private RenderTargetIdentifier source;
   216→        private RenderTargetHandle tempTexture;
   217→
   218→        public CustomPostProcessPass(CustomSettings settings)
   219→        {
   220→            this.settings = settings;
   221→            renderPassEvent = RenderPassEvent.AfterRenderingTransparents;
   222→        }
   223→
   224→        public override void OnCameraSetup(CommandBuffer cmd, ref RenderingData renderingData)
   225→        {
   226→            source = renderingData.cameraData.renderer.cameraColorTarget;
   227→
   228→            var descriptor = renderingData.cameraData.cameraTargetDescriptor;
   229→            descriptor.depthBufferBits = 0;
   230→            cmd.GetTemporaryRT(tempTexture.id, descriptor);
   231→        }
   232→
   233→        public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
   234→        {
   235→            if (settings.material == null) return;
   236→
   237→            CommandBuffer cmd = CommandBufferPool.Get("Custom Post Process");
   238→
   239→            cmd.SetGlobalTexture("_MainTex", source);
   240→            cmd.SetGlobalFloat("_Intensity", settings.intensity);
   241→            cmd.SetGlobalColor("_TintColor", settings.tintColor);
   242→
   243→            cmd.Blit(source, tempTexture.Identifier(), settings.material, 0);
   244→            cmd.Blit(tempTexture.Identifier(), source);
   245→
   246→            context.ExecuteCommandBuffer(cmd);
   247→            CommandBufferPool.Release(cmd);
   248→        }
   249→
   250→        public override void OnCameraCleanup(CommandBuffer cmd)
   251→        {
   252→            cmd.ReleaseTemporaryRT(tempTexture.id);
   253→        }
   254→    }
   255→}
   256→```
