   260→## 4. 三消游戏后处理应用
   261→
   262→```csharp
   263→using UnityEngine.Rendering;
   264→using UnityEngine.Rendering.Universal;
   265→
   266→/// <summary>
   267→/// 三消游戏后处理控制器
   268→/// </summary>
   269→public class Match3PostProcessController : MonoBehaviour
   270→{
   271→    [Header("Post Processing")]
   272→    [SerializeField] private VolumeProfile volumeProfile;
   273→
   274→    private ColorAdjustments colorAdjustments;
   275→    private Bloom bloom;
   276→    private Vignette vignette;
   277→
   278→    [Header("Game State Effects")]
   279→    [SerializeField] private float normalSaturation = 1.0f;
   280→    [SerializeField] private float comboSaturation = 1.5f;
   281→    [SerializeField] private float gameOverVignette = 0.5f;
   282→    [SerializeField] private float victoryBloom = 1.0f;
   283→
   284→    private void Start()
   285→    {
   286→        InitializeEffects();
   287→    }
   288→
   289→    private void InitializeEffects()
   290→    {
   291→        if (volumeProfile == null) return;
   292→
   293→        colorAdjustments = volumeProfile.Add<ColorAdjustments>();
   294→        bloom = volumeProfile.Add<Bloom>();
   295→        vignette = volumeProfile.Add<Vignette>();
   296→
   297→        SetNormalState();
   298→    }
   299→
   300→    public void SetNormalState()
   301→    {
   302→        colorAdjustments?.saturation.Override(normalSaturation);
   303→        bloom?.intensity.Override(0.3f);
   304→        vignette?.intensity.Override(0.2f);
   305→    }
   306→
   307→    public void OnCombo(int comboCount)
   308→    {
   309→        float saturationBoost = normalSaturation + comboCount * 0.1f;
   310→        colorAdjustments?.saturation.Override(Mathf.Clamp01(saturationBoost, 0, 2));
   311→        bloom?.intensity.Override(0.5f + comboCount * 0.1f);
   312→    }
   313→
   314→    public void OnGameOver()
   315→    {
   316→        colorAdjustments?.saturation.Override(0);
   317→        vignette?.intensity.Override(gameOverVignette);
   318→        bloom?.intensity.Override(0);
   319→    }
   320→
   321→    public void OnVictory()
   322→    {
   323→        colorAdjustments?.saturation.Override(1.5f);
   324→        bloom?.intensity.Override(victoryBloom);
   325→        vignette?.intensity.Override(0.1f);
   326→    }
   327→
   328→    public void TransitionTo(float targetSaturation, float targetVignette, float duration)
   329→    {
   330→        StartCoroutine(TransitionCoroutine(targetSaturation, targetVignette, duration));
   331→    }
   332→
   333→    private IEnumerator TransitionCoroutine(float targetSaturation, float targetVignette, float duration)
   334→    {
   335→        float startSaturation = colorAdjustments.saturation.value;
   336→        float startVignette = vignette.intensity.value;
   337→
   338→        float elapsed = 0;
   339→
   340→        while (elapsed < duration)
   341→        {
   342→            elapsed += Time.deltaTime;
   343→            float t = elapsed / duration;
   344→
   345→            colorAdjustments?.saturation.Override(Mathf.Lerp(startSaturation, targetSaturation, t));
   346→            vignette?.intensity.Override(Mathf.Lerp(startVignette, targetVignette, t));
   347→
   348→            yield return null;
   349→        }
   350→
   351→        colorAdjustments?.saturation.Override(targetSaturation);
   352→        vignette?.intensity.Override(targetVignette);
   353→    }
   354→}
   355→```
