```csharp
public class PerformanceSettings : MonoBehaviour
{
    public int qualityLevel = 2; // 0=低, 1=中, 2=高

    void SetQuality()
    {
        switch (qualityLevel)
        {
            case 0: // 低质量
                DisableExpensiveEffects();
                break;
            case 1: // 中质量
                EnableMediumEffects();
                break;
            case 2: // 高质量
                EnableAllEffects();
                break;
        }
    }

    void DisableExpensiveEffects()
    {
        // 禁用昂贵的后处理效果
        // Bloom: 关闭
        // DOF: 关闭
    }
}
```

