    45→## 一、状态同步模型
    46→
    47→### 基本原理
    48→
    49→```
    50→客户端A                    服务器                    客户端B
    51→   │                        │                          │
    52→   │──── 输入 ────────────>│                          │
    53→   │                        │──── 状态广播 ───────────>│
    54→   │                        │                          │
    55→   │<────────────────── 状态广播 ──────────────────────│
    56→   │                        │                          │
    57→```
    58→
    59→### 实现
    60→
    61→```csharp
    62→using System;
    63→using System.Collections.Generic;
    64→using UnityEngine;
    65→
    66→/// <summary>
    67→/// 网络状态同步管理器
    68→/// </summary>
    69→public class StateSynchronization : MonoBehaviour
    70→{
    71→    [Header("同步配置")]
    72→    [SerializeField] private float syncInterval = 0.05f;  // 20次/秒
    73→    [SerializeField] private float positionThreshold = 0.1f;
    74→    [SerializeField] private float rotationThreshold = 5f;
    75→
    76→    private float lastSyncTime;
    77→    private readonly Dictionary<int, NetworkEntity> entities = new Dictionary<int, NetworkEntity>();
    78→
    79→    /// <summary>
    80→    /// 网络实体数据
    81→    /// </summary>
    82→    public struct EntityState
    83→    {
    84→        public int entityId;
    85→        public Vector3 position;
    86→        public Quaternion rotation;
    87→        public Vector3 velocity;
    88→        public float timestamp;
    89→    }
    90→
    91→    /// <summary>
    92→    /// 网络实体
    93→    /// </summary>
    94→    public class NetworkEntity : MonoBehaviour
    95→    {
    96→        public int entityId;
    97→        public bool isOwner;
    98→
    99→        private Vector3 lastSentPosition;
   100→        private Quaternion lastSentRotation;
   101→
   102→        public EntityState GetState()
   103→        {
   104→            return new EntityState
   105→            {
   106→                entityId = entityId,
   107→                position = transform.position,
   108→                rotation = transform.rotation,
   109→                velocity = GetComponent<Rigidbody>()?.velocity ?? Vector3.zero,
   110→                timestamp = Time.time
   111→            };
   112→        }
   113→
   114→        public bool HasStateChanged(float posThreshold, float rotThreshold)
   115→        {
   116→            if (Vector3.Distance(transform.position, lastSentPosition) > posThreshold)
   117→                return true;
   118→
   119→            if (Quaternion.Angle(transform.rotation, lastSentRotation) > rotThreshold)
   120→                return true;
   121→
   122→            return false;
   123→        }
   124→
   125→        public void MarkSynced()
   126→        {
   127→            lastSentPosition = transform.position;
   128→            lastSentRotation = transform.rotation;
   129→        }
   130→    }
   131→
   132→    /// <summary>
   133→    /// 序列化状态数据
   134→    /// </summary>
   135→    public static byte[] SerializeState(EntityState state)
   136→    {
   137→        var data = new byte[48];  // 4 + 12 + 16 + 12 + 4
   138→        int offset = 0;
   139→
   140→        // Entity ID
   141→        BitConverter.TryWriteBytes(data.AsSpan(offset), state.entityId); offset += 4;
   142→
   143→        // Position
   144→        BitConverter.TryWriteBytes(data.AsSpan(offset), state.position.x); offset += 4;
   145→        BitConverter.TryWriteBytes(data.AsSpan(offset), state.position.y); offset += 4;
   146→        BitConverter.TryWriteBytes(data.AsSpan(offset), state.position.z); offset += 4;
   147→
   148→        // Rotation (quaternion)
   149→        BitConverter.TryWriteBytes(data.AsSpan(offset), state.rotation.x); offset += 4;
   150→        BitConverter.TryWriteBytes(data.AsSpan(offset), state.rotation.y); offset += 4;
   151→        BitConverter.TryWriteBytes(data.AsSpan(offset), state.rotation.z); offset += 4;
   152→        BitConverter.TryWriteBytes(data.AsSpan(offset), state.rotation.w); offset += 4;
   153→
   154→        // Velocity
   155→        BitConverter.TryWriteBytes(data.AsSpan(offset), state.velocity.x); offset += 4;
   156→        BitConverter.TryWriteBytes(data.AsSpan(offset), state.velocity.y); offset += 4;
   157→        BitConverter.TryWriteBytes(data.AsSpan(offset), state.velocity.z); offset += 4;
   158→
   159→        // Timestamp
   160→        BitConverter.TryWriteBytes(data.AsSpan(offset), state.timestamp);
   161→
   162→        return data;
   163→    }
   164→
   165→    /// <summary>
   166→    /// 反序列化状态数据
   167→    /// </summary>
   168→    public static EntityState DeserializeState(byte[] data, int offset = 0)
   169→    {
   170→        var state = new EntityState();
   171→
   172→        state.entityId = BitConverter.ToInt32(data, offset); offset += 4;
   173→
   174→        state.position = new Vector3(
   175→            BitConverter.ToSingle(data, offset),
   176→            BitConverter.ToSingle(data, offset + 4),
   177→            BitConverter.ToSingle(data, offset + 8)
   178→        ); offset += 12;
   179→
   180→        state.rotation = new Quaternion(
   181→            BitConverter.ToSingle(data, offset),
   182→            BitConverter.ToSingle(data, offset + 4),
   183→            BitConverter.ToSingle(data, offset + 8),
   184→            BitConverter.ToSingle(data, offset + 12)
   185→        ); offset += 16;
   186→
   187→        state.velocity = new Vector3(
   188→            BitConverter.ToSingle(data, offset),
   189→            BitConverter.ToSingle(data, offset + 4),
   190→            BitConverter.ToSingle(data, offset + 8)
   191→        ); offset += 12;
   192→
   193→        state.timestamp = BitConverter.ToSingle(data, offset);
   194→
   195→        return state;
   196→    }
   197→
   198→    private void Update()
   199→    {
   200→        if (Time.time - lastSyncTime >= syncInterval)
   201→        {
   202→            SyncEntities();
   203→            lastSyncTime = Time.time;
   204→        }
   205→    }
   206→
   207→    private void SyncEntities()
   208→    {
   209→        foreach (var kvp in entities)
   210→        {
   211→            var entity = kvp.Value;
   212→
   213→            // 只同步自己拥有的实体
   214→            if (!entity.isOwner) continue;
   215→
   216→            // 检查状态是否变化
   217→            if (entity.HasStateChanged(positionThreshold, rotationThreshold))
   218→            {
   219→                SendStateToServer(entity.GetState());
   220→                entity.MarkSynced();
   221→            }
   222→        }
   223→    }
