   232→    /// <summary>
   233→    /// 处理接收到的状态更新
   234→    /// </summary>
   235→    public void OnStateReceived(EntityState state)
   236→    {
   237→        if (entities.TryGetValue(state.entityId, out var entity))
   238→        {
   239→            if (!entity.isOwner)  // 不覆盖自己控制的实体
   240→            {
   241→                ApplyState(entity, state);
   242→            }
   243→        }
   244→    }
   245→
   246→    /// <summary>
   247→    /// 应用状态到实体
   248→    /// </summary>
   249→    private void ApplyState(NetworkEntity entity, EntityState state)
   250→    {
   251→        // 使用插值平滑过渡
   252→        StartCoroutine(InterpolateToState(entity, state));
   253→    }
   254→
   255→    private System.Collections.IEnumerator InterpolateToState(NetworkEntity entity, EntityState state)
   256→    {
   257→        var startPos = entity.transform.position;
   258→        var startRot = entity.transform.rotation;
   259→        var targetPos = state.position;
   260→        var targetRot = state.rotation;
   261→
   262→        float duration = syncInterval;
   263→        float elapsed = 0f;
   264→
   265→        while (elapsed < duration)
   266→        {
   267→            elapsed += Time.deltaTime;
   268→            float t = elapsed / duration;
   269→
   270→            entity.transform.position = Vector3.Lerp(startPos, targetPos, t);
   271→            entity.transform.rotation = Quaternion.Slerp(startRot, targetRot, t);
   272→
   273→            yield return null;
   274→        }
   275→
   276→        entity.transform.position = targetPos;
   277→        entity.transform.rotation = targetRot;
   278→    }
   279→}
