   284→## 二、客户端预测
   285→
   286→### 原理图
   287→
   288→```
   289→┌──────────────────────────────────────────────────────────────┐
   290→│                      客户端预测流程                           │
   291→├──────────────────────────────────────────────────────────────┤
   292→│                                                              │
   293→│  输入 ──> 本地立即执行 ──> 发送到服务器 ──> 接收服务器确认    │
   294→│              │                                     │          │
   295→│              v                                     v          │
   296→│           预测状态 <─────────── 比较 ──────────  服务器状态   │
   297→│                                    │                         │
   298→│                              误差 > 阈值?                     │
   299→│                               │        │                     │
   300→│                              Yes       No                    │
   301→│                               │        │                     │
   302→│                           回滚修正    继续执行                │
   303→│                                                              │
   304→└──────────────────────────────────────────────────────────────┘
   305→```
   306→
   307→### 实现
   308→
   309→```csharp
   310→using System.Collections.Generic;
   311→using UnityEngine;
   312→
   313→/// <summary>
   314→/// 客户端预测系统
   315→/// </summary>
   316→public class ClientPrediction : MonoBehaviour
   317→{
   318→    [Header("预测配置")]
   319→    [SerializeField] private float reconciliationThreshold = 2f;  // 2米误差触发修正
   320→    [SerializeField] private int maxStoredInputs = 60;  // 存储60帧输入
   321→
   322→    private struct PredictedState
   323→    {
   324→        public Vector3 position;
   325→        public Quaternion rotation;
   326→        public int inputSequence;
   327→        public float timestamp;
   328→    }
   329→
   330→    private struct PlayerInput
   331→    {
   332→        public float horizontal;
   333→        public float vertical;
   334→        public bool jump;
   335→        public int sequence;
   336→        public float timestamp;
   337→    }
   338→
   339→    private readonly Queue<PlayerInput> pendingInputs = new Queue<PlayerInput>();
   340→    private readonly List<PredictedState> predictedStates = new List<PredictedState>();
   341→    private int inputSequence;
   342→
   343→    private CharacterController controller;
   344→    private Vector3 velocity;
   345→    private bool isGrounded;
   346→
   347→    public event Action<PlayerInput> OnInputSent;
   348→
   349→    private void Awake()
   350→    {
   351→        controller = GetComponent<CharacterController>();
   352→    }
   353→
   354→    private void Update()
   355→    {
   356→        // 收集输入
   357→        var input = CollectInput();
   358→
   359→        // 本地预测执行
   360→        ApplyInput(input);
   361→
   362→        // 存储预测状态
   363→        StorePrediction(input);
   364→
   365→        // 发送输入到服务器
   366→        SendInputToServer(input);
   367→    }
   368→
   369→    private PlayerInput CollectInput()
   370→    {
   371→        return new PlayerInput
   372→        {
   373→            horizontal = Input.GetAxis("Horizontal"),
   374→            vertical = Input.GetAxis("Vertical"),
   375→            jump = Input.GetButtonDown("Jump"),
   376→            sequence = inputSequence++,
   377→            timestamp = Time.time
   378→        };
   379→    }
   380→
   381→    /// <summary>
   382→    /// 本地预测执行输入
   383→    /// </summary>
   384→    private void ApplyInput(PlayerInput input)
   385→    {
   386→        // 移动
   387→        Vector3 move = new Vector3(input.horizontal, 0, input.vertical);
   388→        controller.Move(move * 5f * Time.deltaTime);
   389→
   390→        // 重力
   391→        isGrounded = controller.isGrounded;
   392→        if (!isGrounded)
   393→        {
   394→            velocity.y += Physics.gravity.y * Time.deltaTime;
   395→        }
   396→        else if (velocity.y < 0)
   397→        {
   398→            velocity.y = -2f;
   399→        }
   400→
   401→        // 跳跃
   402→        if (input.jump && isGrounded)
   403→        {
   404→            velocity.y = 5f;
   405→        }
   406→
   407→        controller.Move(velocity * Time.deltaTime);
   408→    }
   409→
   410→    private void StorePrediction(PlayerInput input)
   411→    {
   412→        predictedStates.Add(new PredictedState
   413→        {
   414→            position = transform.position,
   415→            rotation = transform.rotation,
   416→            inputSequence = input.sequence,
   417→            timestamp = Time.time
   418→        });
   419→
   420→        // 限制存储数量
   421→        if (predictedStates.Count > maxStoredInputs)
   422→        {
   423→            predictedStates.RemoveAt(0);
   424→        }
   425→
   426→        pendingInputs.Enqueue(input);
   427→    }
   428→
   429→    private void SendInputToServer(PlayerInput input)
   430→    {
   431→        OnInputSent?.Invoke(input);
   432→    }
   433→
   434→    /// <summary>
   435→    /// 处理服务器确认的状态
   436→    /// </summary>
   437→    public void OnServerStateReceived(Vector3 serverPosition, int ackSequence)
   438→    {
   439→        // 移除已确认的输入
   440→        while (pendingInputs.Count > 0 && pendingInputs.Peek().sequence <= ackSequence)
   441→        {
   442→            pendingInputs.Dequeue();
   443→        }
   444→
   445→        // 查找对应的预测状态
   446→        var predictedState = predictedStates.Find(s => s.inputSequence == ackSequence);
   447→
   448→        if (predictedState.position != Vector3.zero)
   449→        {
   450→            float error = Vector3.Distance(predictedState.position, serverPosition);
   451→
   452→            if (error > reconciliationThreshold)
   453→            {
   454→                // 误差过大，需要修正
   455→                Debug.Log($"状态修正: 误差 {error:F2}米");
   456→                Reconcile(serverPosition, ackSequence);
   457→            }
   458→        }
   459→
   460→        // 清理已确认的预测状态
   461→        predictedStates.RemoveAll(s => s.inputSequence <= ackSequence);
   462→    }
   463→
   464→    /// <summary>
   465→    /// 状态修正
   466→    /// </summary>
   467→    private void Reconcile(Vector3 serverPosition, int fromSequence)
   468→    {
   469→        // 1. 回滚到服务器状态
   470→        transform.position = serverPosition;
   471→
   472→        // 2. 重放未确认的输入
   473→        foreach (var input in pendingInputs)
   474→        {
   475→            ApplyInput(input);
   476→        }
   477→
   478→        Debug.Log("状态修正完成");
   479→    }
   480→}
   481→```
