   485→## 三、延迟补偿
   486→
   487→### 原理
   488→
   489→```
   490→┌────────────────────────────────────────────────────────────┐
   491→│                    延迟补偿原理                             │
   492→├────────────────────────────────────────────────────────────┤
   493→│                                                            │
   494→│  时间线: ──────────────────────────────────────────────>   │
   495→│                                                            │
   496→│  客户端A (RTT=100ms)                                       │
   497→│     │                                                      │
   498→│     ├──── t=0 ──── 发送射击 ───────────────────────┐       │
   499→│     │                                              │       │
   500→│     │<──── t=100ms ── 收到确认                     │       │
   501→│     │                                              │       │
   502→│  服务器                                           │       │
   503→│     │                                              │       │
   504→│     ├──── t=50ms ──── 收到射击请求 ────────────────┘       │
   505→│     │                                                      │
   506→│     │   回滚客户端B到 t-50ms 时的位置                       │
   507→│     │   进行命中判定                                        │
   508→│     │                                                      │
   509→│     ├──── t=50ms ──── 发送结果给双方                       │
   510→│     │                                                      │
   511→└────────────────────────────────────────────────────────────┘
   512→```
   513→
   514→### 实现
   515→
   516→```csharp
   517→using System.Collections.Generic;
   518→using UnityEngine;
   519→
   520→/// <summary>
   521→/// 服务器端延迟补偿
   522→/// </summary>
   523→public class LagCompensation : MonoBehaviour
   524→{
   525→    [Header("补偿配置")]
   526→    [SerializeField] private float historyDuration = 1f;  // 存储1秒历史
   527→    [SerializeField] private float snapshotInterval = 0.05f;  // 20Hz
   528→
   529→    private struct PlayerSnapshot
   530→    {
   531→        public int playerId;
   532→        public Vector3 position;
   533→        public Quaternion rotation;
   534→        public Bounds hitbox;
   535→        public float timestamp;
   536→    }
   537→
   538→    private class PlayerHistory
   539→    {
   540→        public int playerId;
   541→        public Transform transform;
   542→        public Collider hitbox;
   543→        public readonly List<PlayerSnapshot> snapshots = new List<PlayerSnapshot>();
   544→    }
   545→
   546→    private readonly Dictionary<int, PlayerHistory> playerHistories = new Dictionary<int, PlayerHistory>();
   547→
   548→    /// <summary>
   549→    /// 记录玩家快照
   550→    /// </summary>
   551→    private void RecordSnapshots()
   552→    {
   553→        float currentTime = Time.time;
   554→        float cutoffTime = currentTime - historyDuration;
   555→
   556→        foreach (var history in playerHistories.Values)
   557→        {
   558→            // 添加新快照
   559→            history.snapshots.Add(new PlayerSnapshot
   560→            {
   561→                playerId = history.playerId,
   562→                position = history.transform.position,
   563→                rotation = history.transform.rotation,
   564→                hitbox = history.hitbox.bounds,
   565→                timestamp = currentTime
   566→            });
   567→
   568→            // 移除过期快照
   569→            history.snapshots.RemoveAll(s => s.timestamp < cutoffTime);
   570→        }
   571→    }
   572→
   573→    /// <summary>
   574→    /// 获取指定时间点的玩家状态
   575→    /// </summary>
   576→    private PlayerSnapshot GetSnapshotAtTime(int playerId, float targetTime)
   577→    {
   578→        if (!playerHistories.TryGetValue(playerId, out var history))
   579→        {
   580→            return default;
   581→        }
   582→
   583→        // 查找最近的两个快照
   584→        PlayerSnapshot before = default;
   585→        PlayerSnapshot after = default;
   586→
   587→        foreach (var snapshot in history.snapshots)
   588→        {
   589→            if (snapshot.timestamp <= targetTime)
   590→            {
   591→                before = snapshot;
   592→            }
   593→            else if (after.timestamp == 0)
   594→            {
   595→                after = snapshot;
   596→                break;
   597→            }
   598→        }
   599→
   600→        if (before.timestamp == 0) return after;
   601→        if (after.timestamp == 0) return before;
   602→
   603→        // 插值
   604→        float t = (targetTime - before.timestamp) / (after.timestamp - before.timestamp);
   605→        return InterpolateSnapshots(before, after, t);
   606→    }
   607→
   608→    private PlayerSnapshot InterpolateSnapshots(PlayerSnapshot a, PlayerSnapshot b, float t)
   609→    {
   610→        return new PlayerSnapshot
   611→        {
   612→            playerId = a.playerId,
   613→            position = Vector3.Lerp(a.position, b.position, t),
   614→            rotation = Quaternion.Slerp(a.rotation, b.rotation, t),
   615→            hitbox = InterpolateBounds(a.hitbox, b.hitbox, t),
   616→            timestamp = Mathf.Lerp(a.timestamp, b.timestamp, t)
   617→        };
   618→    }
   619→
   620→    private Bounds InterpolateBounds(Bounds a, Bounds b, float t)
   621→    {
   622→        return new Bounds
   623→        {
   624→            center = Vector3.Lerp(a.center, b.center, t),
   625→            size = Vector3.Lerp(a.size, b.size, t)
   626→        };
   627→    }
   628→
   629→    /// <summary>
   630→    /// 执行延迟补偿的命中检测
   631→    /// </summary>
   632→    public bool CheckHit(int shooterPlayerId, Vector3 origin, Vector3 direction, float latency, out int hitPlayerId)
   633→    {
   634→        hitPlayerId = -1;
   635→
   636→        // 计算射击时的服务器时间
   637→        float shootTime = Time.time - (latency / 2f);
   638→
   639→        // 临时回滚所有玩家
   640→        var originalStates = new Dictionary<int, (Vector3 pos, Quaternion rot)>();
   641→
   642→        foreach (var history in playerHistories.Values)
   643→        {
   644→            if (history.playerId == shooterPlayerId) continue;
   645→
   646→            originalStates[history.playerId] = (history.transform.position, history.transform.rotation);
   647→
   648→            var snapshot = GetSnapshotAtTime(history.playerId, shootTime);
   649→            history.transform.position = snapshot.position;
   650→            history.transform.rotation = snapshot.rotation;
   651→        }
   652→
   653→        // 执行射线检测
   654→        bool hit = Physics.Raycast(origin, direction, out var hitInfo, 100f);
   655→
   656→        if (hit && hitInfo.collider != null)
   657→        {
   658→            // 查找被击中的玩家
   659→            foreach (var history in playerHistories.Values)
   660→            {
   661→                if (history.hitbox == hitInfo.collider)
   662→                {
   663→                    hitPlayerId = history.playerId;
   664→                    break;
   665→                }
   666→            }
   667→        }
   668→
   669→        // 恢复所有玩家位置
   670→        foreach (var kvp in originalStates)
   671→        {
   672→            if (playerHistories.TryGetValue(kvp.Key, out var history))
   673→            {
   674→                history.transform.position = kvp.Value.pos;
   675→                history.transform.rotation = kvp.Value.rot;
   676→            }
   677→        }
   678→
   679→        return hit && hitPlayerId >= 0;
   680→    }
   681→
   682→    /// <summary>
   683→    /// 注册玩家
   684→    /// </summary>
   685→    public void RegisterPlayer(int playerId, Transform transform, Collider hitbox)
   686→    {
   687→        playerHistories[playerId] = new PlayerHistory
   688→        {
   689→            playerId = playerId,
   690→            transform = transform,
   691→            hitbox = hitbox
   692→        };
   693→    }
   694→
   695→    /// <summary>
   696→    /// 注销玩家
   697→    /// </summary>
   698→    public void UnregisterPlayer(int playerId)
   699→    {
   700→        playerHistories.Remove(playerId);
   701→    }
   702→}
