   707→## 四、插值与平滑
   708→
   709→### 远程实体插值
   710→
   711→```csharp
   712→using UnityEngine;
   713→
   714→/// <summary>
   715→/// 网络实体插值器
   716→/// </summary>
   717→public class NetworkInterpolator : MonoBehaviour
   718→{
   719→    [Header("插值配置")]
   720→    [SerializeField] private float interpolationDelay = 0.1f;  // 100ms延迟
   721→    [SerializeField] private float extrapolationLimit = 0.5f;  // 最大外推时间
   722→
   723→    private struct StateSample
   724→    {
   725→        public Vector3 position;
   726→        public Quaternion rotation;
   727→        public Vector3 velocity;
   728→        public double timestamp;
   729→    }
   730→
   731→    private readonly StateSample[] stateBuffer = new StateSample[20];
   732→    private int bufferIndex;
   733→
   734→    private double renderTime;
   735→
   736→    /// <summary>
   737→    /// 添加服务器状态样本
   738→    /// </summary>
   739→    public void AddState(Vector3 position, Quaternion rotation, Vector3 velocity, double serverTime)
   740→    {
   741→        var state = new StateSample
   742→        {
   743→            position = position,
   744→            rotation = rotation,
   745→            velocity = velocity,
   746→            timestamp = serverTime
   747→        };
   748→
   749→        stateBuffer[bufferIndex] = state;
   750→        bufferIndex = (bufferIndex + 1) % stateBuffer.Length;
   751→    }
   752→
   753→    private void Update()
   754→    {
   755→        // 计算插值目标时间
   756→        renderTime = NetworkTime.Time - interpolationDelay;
   757→
   758→        // 查找插值点
   759→        if (TryFindInterpolationPoints(out var before, out var after, out float t))
   760→        {
   761→            // 插值位置
   762→            transform.position = Vector3.Lerp(before.position, after.position, t);
   763→            transform.rotation = Quaternion.Slerp(before.rotation, after.rotation, t);
   764→        }
   765→        else
   766→        {
   767→            // 没有足够数据，使用外推
   768→            Extrapolate();
   769→        }
   770→    }
   771→
   772→    private bool TryFindInterpolationPoints(out StateSample before, out StateSample after, out float t)
   773→    {
   774→        before = default;
   775→        after = default;
   776→        t = 0f;
   777→
   778→        // 查找renderTime前后的两个样本
   779→        for (int i = 0; i < stateBuffer.Length - 1; i++)
   780→        {
   781→            int idx = (bufferIndex - 2 - i + stateBuffer.Length) % stateBuffer.Length;
   782→            int nextIdx = (idx + 1) % stateBuffer.Length;
   783→
   784→            if (stateBuffer[idx].timestamp <= renderTime && stateBuffer[nextIdx].timestamp >= renderTime)
   785→            {
   786→                before = stateBuffer[idx];
   787→                after = stateBuffer[nextIdx];
   788→
   789→                double duration = after.timestamp - before.timestamp;
   790→                if (duration > 0)
   791→                {
   792→                    t = (float)((renderTime - before.timestamp) / duration);
   793→                }
   794→
   795→                return true;
   796→            }
   797→        }
   798→
   799→        return false;
   800→    }
   801→
   802→    private void Extrapolate()
   803→    {
   804→        // 找最新的状态
   805→        var latest = stateBuffer[(bufferIndex - 1 + stateBuffer.Length) % stateBuffer.Length];
   806→
   807→        if (latest.timestamp == 0) return;
   808→
   809→        float timeSinceLastUpdate = (float)(NetworkTime.Time - latest.timestamp);
   810→
   811→        if (timeSinceLastUpdate < extrapolationLimit)
   812→        {
   813→            // 线性外推
   814→            transform.position = latest.position + latest.velocity * timeSinceLastUpdate;
   815→        }
   816→    }
   817→}
   818→
   819→/// <summary>
   820→/// 网络时间（简化版）
   821→/// </summary>
