    26→
    27→## 1. 同步模型概述
    28→
    29→### 1.1 三种主流模型
    30→
    31→| 模型 | 特点 | 适用场景 |
    32→|------|------|----------|
    33→| **状态同步** | 同步游戏状态 | MMO、FPS |
    34→| **帧同步** | 同步玩家输入 | MOBA、RTS |
    35→| **预测回滚** | 本地预测+服务器校正 | 格斗、FPS |
    36→
    37→---
    38→
    39→## 2. 状态同步
    40→
    41→### 2.1 原理
    42→
    43→```
    44→客户端 A                服务器                客户端 B
    45→   │                      │                      │
    46→   ├─── 发送位置 ────────→│                      │
    47→   │                      ├─── 广播位置 ─────────→
    48→   │                      │                      │
    49→   │                      │←──── 发送位置 ────────┤
    50→   │←──── 广播位置 ───────┤                      │
    51→```
    52→
    53→### 2.2 实现
    54→
    55→```csharp
    56→using System.Collections.Generic;
    57→using UnityEngine;
    58→
    59→public class StateSyncClient : MonoBehaviour
    60→{
    61→    private float syncInterval = 0.05f;  // 20次/秒
    62→    private float lastSyncTime;
    63→    private Vector3 lastSyncPosition;
    64→    private NetworkClient networkClient;
    65→
    66→    // 状态快照
    67→    private struct StateSnapshot
    68→    {
    69→        public float timestamp;
    70→        public Vector3 position;
    71→        public Quaternion rotation;
    72→    }
    73→
    74→    private Queue<StateSnapshot> serverStates = new Queue<StateSnapshot>();
    75→
    76→    private void Update()
    77→    {
    78→        // 发送本地状态
    79→        if (IsLocalPlayer() && Time.time - lastSyncTime >= syncInterval)
    80→        {
    81→            SendStateToServer();
    82→            lastSyncTime = Time.time;
    83→        }
    84→
    85→        // 插值显示其他玩家
    86→        if (!IsLocalPlayer())
    87→        {
    88→            InterpolatePosition();
    89→        }
    90→    }
    91→
    92→    private void SendStateToServer()
    93→    {
    94→        Vector3 position = transform.position;
    95→        Quaternion rotation = transform.rotation;
    96→
    97→        // 只有位置变化才发送
    98→        if (Vector3.Distance(position, lastSyncPosition) > 0.01f)
    99→        {
   100→            var packet = new PositionPacket
   101→            {
   102→                x = position.x,
   103→                y = position.y,
   104→                z = position.z,
   105→                rotX = rotation.eulerAngles.x,
   106→                rotY = rotation.eulerAngles.y,
   107→                rotZ = rotation.eulerAngles.z,
   108→                timestamp = Time.time
   109→            };
   110→
   111→            networkClient.Send(packet);
   112→            lastSyncPosition = position;
   113→        }
   114→    }
   115→
   116→    // 接收服务器状态
   117→    public void OnServerStateReceived(StateSnapshot snapshot)
   118→    {
   119→        serverStates.Enqueue(snapshot);
   120→
   121→        // 限制缓冲区大小
   122→        while (serverStates.Count > 10)
   123→        {
   124→            serverStates.Dequeue();
   125→        }
   126→    }
   127→
   128→    // 插值平滑显示
   129→    private float interpolationDelay = 0.1f;  // 100ms 延迟
   130→
   131→    private void InterpolatePosition()
   132→    {
   133→        if (serverStates.Count < 2) return;
   134→
   135→        float renderTime = Time.time - interpolationDelay;
   136→
   137→        // 找到两个快照进行插值
   138→        StateSnapshot[] snapshots = serverStates.ToArray();
   139→
   140→        for (int i = 0; i < snapshots.Length - 1; i++)
   141→        {
   142→            if (snapshots[i].timestamp <= renderTime && snapshots[i + 1].timestamp >= renderTime)
   143→            {
   144→                float t = (renderTime - snapshots[i].timestamp) /
   145→                          (snapshots[i + 1].timestamp - snapshots[i].timestamp);
   146→
   147→                transform.position = Vector3.Lerp(snapshots[i].position, snapshots[i + 1].position, t);
   148→                break;
   149→            }
   150→        }
   151→    }
   152→
   153→    private bool IsLocalPlayer() => true;
   154→}
   155→```
   156→
