   221→
   222→## 3. 帧同步
   223→
   224→### 3.1 原理
   225→
   226→```
   227→回合 1: 所有客户端发送输入 → 服务器收集 → 广播输入 → 所有客户端执行
   228→回合 2: 所有客户端发送输入 → 服务器收集 → 广播输入 → 所有客户端执行
   229→...
   230→```
   231→
   232→**关键点**：
   233→- 所有客户端**确定性执行**
   234→- 只同步**输入**，不同步状态
   235→- 每回合等待所有玩家输入
   236→
   237→### 3.2 实现
   238→
   239→```csharp
   240→using System.Collections.Generic;
   241→
   242→public class FrameSyncManager : MonoBehaviour
   243→{
   244→    private int currentFrame = 0;
   245→    private int framesPerTurn = 5;  // 每回合 5 帧
   246→    private float fixedDeltaTime = 1f / 60f;  // 60 FPS
   247→
   248→    // 输入缓冲
   249→    private Dictionary<int, Dictionary<int, PlayerInput>> turnInputs = new();
   250→
   251→    // 当前回合的输入
   252→    private Dictionary<int, PlayerInput> currentTurnInputs = new();
   253→
   254→    private NetworkClient networkClient;
   255→    private int localPlayerId;
   256→
   257→    private void FixedUpdate()
   258→    {
   259→        currentFrame++;
   260→
   261→        // 收集本地输入
   262→        var localInput = CollectLocalInput();
   263→        currentTurnInputs[localPlayerId] = localInput;
   264→
   265→        // 发送输入到服务器
   266→        networkClient.SendInput(currentFrame, localInput);
   267→
   268→        // 回合结束，执行所有输入
   269→        if (currentFrame % framesPerTurn == 0)
   270→        {
   271→            ExecuteTurn();
   272→        }
   273→    }
   274→
   275→    private PlayerInput CollectLocalInput()
   276→    {
   277→        return new PlayerInput
   278→        {
   279→            moveX = Input.GetAxis("Horizontal"),
   280→            moveY = Input.GetAxis("Vertical"),
   281→            attack = Input.GetButton("Fire1"),
   282→            skillId = GetSkillInput()
   283→        };
   284→    }
   285→
   286→    // 接收服务器广播的输入
   287→    public void OnTurnInputsReceived(int turn, Dictionary<int, PlayerInput> inputs)
   288→    {
   289→        turnInputs[turn] = inputs;
   290→    }
   291→
   292→    private void ExecuteTurn()
   293→    {
   294→        int turn = currentFrame / framesPerTurn;
   295→
   296→        if (!turnInputs.TryGetValue(turn, out var inputs))
   297→        {
   298→            // 等待服务器输入
   299→            return;
   300→        }
   301→
   302→        // 确定性执行所有玩家输入
   303→        foreach (var kvp in inputs)
   304→        {
   305→            int playerId = kvp.Key;
   306→            PlayerInput input = kvp.Value;
   307→
   308→            ExecutePlayerInput(playerId, input);
   309→        }
   310→    }
   311→
   312→    private void ExecutePlayerInput(int playerId, PlayerInput input)
   313→    {
   314→        // 获取玩家实体
   315→        var player = GetPlayerEntity(playerId);
   316→
   317→        // 确定性执行
   318→        player.Move(new Vector3(input.moveX, 0, input.moveY));
   319→
   320→        if (input.attack)
   321→        {
   322→            player.Attack();
   323→        }
   324→
   325→        if (input.skillId > 0)
   326→        {
   327→            player.UseSkill(input.skillId);
   328→        }
   329→    }
   330→
   331→    private object GetPlayerEntity(int playerId) => null;
   332→}
   333→
   334→public struct PlayerInput
   335→{
   336→    public float moveX;
   337→    public float moveY;
   338→    public bool attack;
   339→    public int skillId;
   340→}
   341→```
   342→
   343→### 3.3 确定性要求
   344→
   345→```csharp
   346→// ❌ 错误：使用不确定的值
   347→void BadUpdate()
   348→{
   349→    if (Random.value > 0.5f)  // 每次不同！
   350→    {
   351→        Attack();
   352→    }
   353→}
   354→
   355→// ✅ 正确：使用确定性随机
   356→public class DeterministicRandom
   357→{
   358→    private uint seed;
   359→
   360→    public DeterministicRandom(uint seed)
   361→    {
   362→        this.seed = seed;
   363→    }
   364→
   365→    public int NextInt()
   366→    {
   367→        // Xorshift 算法
   368→        seed ^= seed << 13;
   369→        seed ^= seed >> 17;
   370→        seed ^= seed << 5;
   371→        return (int)(seed & 0x7FFFFFFF);
   372→    }
   373→
   374→    public float NextFloat()
   375→    {
   376→        return NextInt() / (float)int.MaxValue;
   377→    }
   378→}
   379→
   380→// 使用同步的种子
   381→void GoodUpdate(int turnSeed)
   382→{
   383→    var random = new DeterministicRandom((uint)turnSeed);
   384→    if (random.NextFloat() > 0.5f)  // 所有客户端结果相同
   385→    {
   386→        Attack();
   387→    }
   388→}
   389→```
