   392→
   393→## 4. 预测与回滚
   394→
   395→### 4.1 原理
   396→
   397→```
   398→1. 客户端预测：立即执行本地输入
   399→2. 服务器确认：收到服务器状态后校验
   400→3. 回滚修正：如果预测错误，回滚并重新模拟
   401→```
   402→
   403→### 4.2 客户端预测实现
   404→
   405→```csharp
   406→public class PredictionManager : MonoBehaviour
   407→{
   408→    private struct PredictedState
   409→    {
   410→        public int inputSequence;
   411→        public Vector3 position;
   412→        public Quaternion rotation;
   413→    }
   414→
   415→    private Queue<PredictedState> predictedStates = new Queue<PredictedState>();
   416→    private int inputSequence = 0;
   417→
   418→    private Vector3 serverPosition;
   419→    private float reconciliationThreshold = 2f;  // 误差阈值
   420→
   421→    public void ProcessLocalInput(Vector3 input)
   422→    {
   423→        // 本地预测执行
   424→        PredictMovement(input);
   425→
   426→        // 保存预测状态
   427→        predictedStates.Enqueue(new PredictedState
   428→        {
   429→            inputSequence = inputSequence,
   430→            position = transform.position,
   431→            rotation = transform.rotation
   432→        });
   433→
   434→        // 发送输入到服务器
   435→        SendInputToServer(inputSequence, input);
   436→        inputSequence++;
   437→    }
   438→
   439→    private void PredictMovement(Vector3 input)
   440→    {
   441→        // 立即执行移动
   442→        transform.position += input * Time.deltaTime * 5f;
   443→    }
   444→
   445→    // 接收服务器状态
   446→    public void OnServerStateReceived(int sequence, Vector3 serverPos)
   447→    {
   448→        serverPosition = serverPos;
   449→
   450→        // 移除已确认的预测
   451→        while (predictedStates.Count > 0 && predictedStates.Peek().inputSequence <= sequence)
   452→        {
   453→            var confirmed = predictedStates.Dequeue();
   454→
   455→            // 检查误差
   456→            float error = Vector3.Distance(confirmed.position, serverPos);
   457→
   458→            if (error > reconciliationThreshold)
   459→            {
   460→                // 预测错误，需要回滚
   461→                Reconcile(serverPos);
   462→            }
   463→        }
   464→    }
   465→
   466→    private void Reconcile(Vector3 correctPosition)
   467→    {
   468→        // 回滚到正确位置
   469→        transform.position = correctPosition;
   470→
   471→        // 重新模拟所有未确认的输入
   472→        foreach (var state in predictedStates)
   473→        {
   474→            // 重新应用输入（需要保存输入历史）
   475→            // PredictMovement(savedInput);
   476→        }
   477→    }
   478→
   479→    private void SendInputToServer(int seq, Vector3 input)
   480→    {
   481→        // 发送逻辑
   482→    }
   483→}
   484→```
