   540→## 5. 延迟补偿
   541→
   542→### 5.1 服务器端延迟补偿
   543→
   544→```csharp
   545→public class LagCompensation
   546→{
   547→    private struct PlayerHistory
   548→    {
   549→        public float timestamp;
   550→        public Vector3 position;
   551→        public Quaternion rotation;
   552→    }
   553→
   554→    private Dictionary<int, List<PlayerHistory>> playerHistories = new();
   555→    private float historyDuration = 1f;  // 保存 1 秒历史
   556→
   557→    // 记录玩家位置历史
   558→    public void RecordPlayerPosition(int playerId, Vector3 position, Quaternion rotation)
   559→    {
   560→        if (!playerHistories.ContainsKey(playerId))
   561→            playerHistories[playerId] = new List<PlayerHistory>();
   562→
   563→        playerHistories[playerId].Add(new PlayerHistory
   564→        {
   565→            timestamp = Time.time,
   566→            position = position,
   567→            rotation = rotation
   568→        });
   569→
   570→        // 清理过期历史
   571→        var history = playerHistories[playerId];
   572→        history.RemoveAll(h => Time.time - h.timestamp > historyDuration);
   573→    }
   574→
   575→    // 获取指定时间点的玩家位置
   576→    public Vector3 GetPlayerPositionAtTime(int playerId, float targetTime)
   577→    {
   578→        var history = playerHistories[playerId];
   579→
   580→        for (int i = 0; i < history.Count - 1; i++)
   581→        {
   582→            if (history[i].timestamp <= targetTime && history[i + 1].timestamp >= targetTime)
   583→            {
   584→                float t = (targetTime - history[i].timestamp) /
   585→                          (history[i + 1].timestamp - history[i].timestamp);
   586→                return Vector3.Lerp(history[i].position, history[i + 1].position, t);
   587→            }
   588→        }
   589→
   590→        return history[history.Count - 1].position;
   591→    }
   592→
   593→    // 处理射击（带延迟补偿）
