   161→/// <summary>
   162→/// 资源加载服务 - Addressables封装
   163→/// </summary>
   164→public class AssetLoader : MonoBehaviour
   165→{
   166→    private Dictionary<string, AsyncOperationHandle> loadedHandles = new Dictionary<string, AsyncOperationHandle>();
   167→
   168→    /// <summary>
   169→    /// 异步加载单个资源
   170→    /// </summary>
   171→    public async Task<T> LoadAssetAsync<T>(string address) where T : Object
   172→    {
   173→        // 检查缓存
   174→        if (loadedHandles.TryGetValue(address, out var existingHandle))
   175→        {
   176→            if (existingHandle.IsDone)
   177→            {
   178→                return existingHandle.Result as T;
   179→            }
   180→            await existingHandle.Task;
   181→            return existingHandle.Result as T;
   182→        }
   183→
   184→        // 异步加载
   185→        var handle = Addressables.LoadAssetAsync<T>(address);
   186→        loadedHandles[address] = handle;
   187→
   188→        await handle.Task;
   189→
   190→        if (handle.Status == AsyncOperationStatus.Succeeded)
   191→        {
   192→            return handle.Result;
   193→        }
   194→
   195→        Debug.LogError($"Failed to load asset: {address}");
   196→        return null;
   197→    }
   198→
   199→    /// <summary>
   200→    /// 批量异步加载
   201→    /// </summary>
   202→    public async Task<List<T>> LoadAssetsAsync<T>(IList<string> addresses) where T : Object
   203→    {
   204→        var results = new List<T>();
   205→        var tasks = new List<Task<T>>();
   206→
   207→        foreach (var address in addresses)
   208→        {
   209→            tasks.Add(LoadAssetAsync<T>(address));
   210→        }
   211→
   212→        var loadedAssets = await Task.WhenAll(tasks);
   213→        results.AddRange(loadedAssets.Where(a => a != null));
   214→
   215→        return results;
   216→    }
   217→
   218→    /// <summary>
