   292→### 3.2 异步场景加载
   293→
   294→**问题**：SceneManager.LoadScene 同步阻塞
   295→
   296→**方案**：使用 LoadSceneAsync + 进度显示
   297→
   298→```csharp
   299→/// <summary>
   300→/// 场景管理器 - 异步加载版本
   301→/// </summary>
   302→public class SceneLoader : MonoBehaviour
   303→{
   304→    [Header("Loading UI")]
   305→    [SerializeField] private GameObject loadingScreen;
   306→    [SerializeField] private Slider progressBar;
   307→    [SerializeField] private Text progressText;
   308→
   309→    private AsyncOperation currentOperation;
   310→
   311→    /// <summary>
   312→    /// 异步加载场景（带进度显示）
   313→    /// </summary>
   314→    public async Task LoadSceneAsync(string sceneName)
   315→    {
   316→        // 显示加载界面
   317→        loadingScreen.SetActive(true);
   318→        UpdateProgress(0f);
   319→
   320→        // 开始异步加载
   321→        currentOperation = SceneManager.LoadSceneAsync(sceneName);
   322→        currentOperation.allowSceneActivation = false;
   323→
   324→        // 更新进度
   325→        while (!currentOperation.isDone)
   326→        {
   327→            // AsyncOperation.progress 在 allowSceneActivation=false 时最大到0.9
   328→            float progress = Mathf.Clamp01(currentOperation.progress / 0.9f);
   329→            UpdateProgress(progress);
   330→
   331→            // 进度达到90%时，准备激活场景
   332→            if (currentOperation.progress >= 0.9f)
   333→            {
   334→                UpdateProgress(1f);
   335→                await Task.Delay(100); // 短暂延迟让用户看到100%
   336→                currentOperation.allowSceneActivation = true;
   337→            }
   338→
   339→            await Task.Yield();
   340→        }
   341→
   342→        // 隐藏加载界面
   343→        loadingScreen.SetActive(false);
   344→    }
   345→
   346→    /// <summary>
   347→    /// 带预加载的场景切换
   348→    /// </summary>
   349→    public async Task LoadSceneWithPreload(string sceneName, List<string> preloadAssets)
   350→    {
   351→        loadingScreen.SetActive(true);
   352→        UpdateProgress(0f);
   353→
   354→        // 阶段1: 加载场景 (0% - 50%)
   355→        var sceneTask = LoadSceneInternal(sceneName);
   356→        var progressTask = MonitorSceneProgress();
   357→
   358→        await sceneTask;
   359→
   360→        // 阶段2: 预加载资源 (50% - 100%)
   361→        UpdateProgress(0.5f);
   362→        await PreloadAssets(preloadAssets, (p) => UpdateProgress(0.5f + p * 0.5f));
   363→
   364→        UpdateProgress(1f);
   365→        await Task.Delay(100);
   366→
   367→        loadingScreen.SetActive(false);
   368→    }
   369→
   370→    private void UpdateProgress(float progress)
   371→    {
   372→        if (progressBar != null)
   373→        {
   374→            progressBar.value = progress;
   375→        }
   376→        if (progressText != null)
   377→        {
   378→            progressText.text = $"加载中... {(int)(progress * 100)}%";
   379→        }
   380→    }
   381→}
   382→```
   383→
   384→### 3.3 分帧初始化
   385→
   386→**问题**：所有Manager在Awake/Start同步初始化导致卡顿
   387→
   388→**方案**：使用协程分帧初始化
   389→
   390→```csharp
   391→/// <summary>
   392→/// 游戏启动器 - 分帧初始化
   393→/// </summary>
   394→public class GameLauncher : MonoBehaviour
   395→{
   396→    [Header("Initialization Order")]
   397→    [SerializeField] private List<MonoBehaviour> initOrder;
   398→
   399→    [Header("Loading UI")]
   400→    [SerializeField] private Slider initProgress;
   401→    [SerializeField] private Text initStatus;
   402→
   403→    private float initStartTime;
   404→
   405→    private async void Start()
   406→    {
   407→        initStartTime = Time.realtimeSinceStartup;
   408→
   409→        // 阶段1: 核心系统初始化
   410→        await InitializePhase("核心系统", new List<Func<Task>>
   411→        {
   412→            () => InitializeManager<AudioManager>(),
   413→            () => InitializeManager<EventManager>(),
   414→            () => InitializeManager<SaveManager>(),
   415→        });
   416→
   417→        // 阶段2: UI初始化
   418→        await InitializePhase("UI系统", new List<Func<Task>>
   419→        {
   420→            () => InitializeManager<UIManager>(),
   421→            () => PreloadUIAssets(),
   422→        });
   423→
   424→        // 阶段3: 游戏系统初始化
   425→        await InitializePhase("游戏系统", new List<Func<Task>>
   426→        {
   427→            () => InitializeManager<GameManager>(),
   428→            () => InitializeManager<CharacterManager>(),
   429→            () => LoadLevelConfig(),
   430→        });
   431→
   432→        // 阶段4: 可延后初始化
   433→        StartCoroutine(DelayedInit());
   434→    }
   435→
   436→    private async Task InitializePhase(string phaseName, List<Func<Task>> tasks)
   437→    {
   438→        UpdateStatus($"正在初始化{phaseName}...");
   439→
   440→        for (int i = 0; i < tasks.Count; i++)
   441→        {
   442→            await tasks[i]();
   443→            UpdateProgress((float)(i + 1) / tasks.Count);
   444→
   445→            // 每个任务后等待一帧，避免卡顿
   446→            await Task.Yield();
   447→        }
   448→    }
   449→
   450→    private IEnumerator DelayedInit()
   451→    {
   452→        // 等待3秒后初始化非关键系统
   453→        yield return new WaitForSeconds(3f);
   454→
   455→        // 后台初始化分析SDK
   456→        Task.Run(() => AnalyticsService.Initialize());
   457→
   458→        // 后台初始化广告SDK
   459→        Task.Run(() => AdService.Initialize());
   460→    }
   461→
   462→    private void UpdateStatus(string status)
   463→    {
   464→        if (initStatus != null)
   465→        {
   466→            initStatus.text = status;
   467→        }
   468→    }
   469→
   470→    private void UpdateProgress(float progress)
   471→    {
   472→        if (initProgress != null)
   473→        {
   474→            initProgress.value = progress;
   475→        }
   476→    }
   477→
   478→    private async Task InitializeManager<T>() where T : MonoBehaviour
   479→    {
   480→        var manager = FindObjectOfType<T>();
   481→        if (manager is IAsyncInitializable asyncInit)
   482→        {
   483→            await asyncInit.InitializeAsync();
   484→        }
   485→    }
   486→}
   487→
   488→/// <summary>
   489→/// 异步初始化接口
   490→/// </summary>
   491→public interface IAsyncInitializable
   492→{
   493→    Task InitializeAsync();
   494→}
   495→```
