   497→### 3.4 配置预加载
   498→
   499→**问题**：JSON配置在主线程解析阻塞
   500→
   501→**方案**：后台线程预加载 + 缓存
   502→
   503→```csharp
   504→/// <summary>
   505→/// 配置管理器 - 异步加载版本
   506→/// </summary>
   507→public class ConfigManager : MonoBehaviour, IAsyncInitializable
   508→{
   509→    private Dictionary<string, object> configCache = new Dictionary<string, object>();
   510→
   511→    public async Task InitializeAsync()
   512→    {
   513→        // 在后台线程加载所有配置
   514→        var configFiles = new Dictionary<string, Type>
   515→        {
   516→            { "Config/levels", typeof(LevelConfigData) },
   517→            { "Config/characters", typeof(CharacterConfigData) },
   518→            { "Config/items", typeof(ItemConfigData) },
   519→            { "Config/iap", typeof(IAPConfigData) },
   520→        };
   521→
   522→        // 并行加载
   523→        var tasks = configFiles.Select(kvp => LoadConfigAsync(kvp.Key, kvp.Value));
   524→        await Task.WhenAll(tasks);
   525→    }
   526→
   527→    private async Task LoadConfigAsync(string address, Type configType)
   528→    {
   529→        var jsonAsset = await Addressables.LoadAssetAsync<TextAsset>(address).Task;
   530→
   531→        if (jsonAsset != null)
   532→        {
   533→            // 在后台线程解析JSON
   534→            var config = await Task.Run(() =>
   535→            {
   536→                return JsonUtility.FromJson(jsonAsset.text, configType);
   537→            });
   538→
   539→            configCache[address] = config;
   540→        }
   541→    }
   542→
   543→    /// <summary>
   544→    /// 获取配置（同步，必须已预加载）
   545→    /// </summary>
   546→    public T GetConfig<T>(string address) where T : class
   547→    {
   548→        if (configCache.TryGetValue(address, out var config))
   549→        {
   550→            return config as T;
   551→        }
   552→        Debug.LogError($"Config not loaded: {address}");
   553→        return null;
   554→    }
   555→}
   556→```
