   558→### 3.5 智能预加载策略
   559→
   560→**问题**：全部资源一次性加载太慢
   561→
   562→**方案**：按优先级分层预加载
   563→
   564→```csharp
   565→/// <summary>
   566→/// 智能预加载管理器
   567→/// </summary>
   568→public class SmartPreloader : MonoBehaviour
   569→{
   570→    [System.Serializable]
   571→    public class PreloadGroup
   572→    {
   573→        public string groupName;
   574→        public List<string> assetAddresses;
   575→        public PreloadPriority priority;
   576→        public bool showInLoading;
   577→    }
   578→
   579→    public enum PreloadPriority
   580→    {
   581→        Critical,   // 启动必须，立即加载
   582→        High,       // 首屏需要，启动后加载
   583→        Normal,     // 游戏中需要，后台加载
   584→        Low         // 可选内容，空闲加载
   585→    }
   586→
   587→    [Header("Preload Groups")]
   588→    [SerializeField] private List<PreloadGroup> preloadGroups;
   589→
   590→    private Dictionary<string, float> loadProgress = new Dictionary<string, float>();
   591→
   592→    /// <summary>
   593→    /// 开始预加载
   594→    /// </summary>
   595→    public async Task StartPreload(Action<float> onProgress)
   596→    {
   597→        // 按优先级分组
   598→        var criticalGroup = preloadGroups.Where(g => g.priority == PreloadPriority.Critical);
   599→        var highGroup = preloadGroups.Where(g => g.priority == PreloadPriority.High);
   600→        var normalGroup = preloadGroups.Where(g => g.priority == PreloadPriority.Normal);
   601→        var lowGroup = preloadGroups.Where(g => g.priority == PreloadPriority.Low);
   602→
   603→        int totalGroups = preloadGroups.Count;
   604→        int completedGroups = 0;
   605→
   606→        // 1. 加载关键资源（阻塞）
   607→        foreach (var group in criticalGroup)
   608→        {
   609→            await LoadGroup(group);
   610→            completedGroups++;
   611→            onProgress?.Invoke((float)completedGroups / totalGroups);
   612→        }
   613→
   614→        // 2. 启动游戏（关键资源加载完成即可）
   615→        // ... 允许玩家进入游戏 ...
   616→
   617→        // 3. 后台加载高优先级资源
   618→        _ = Task.Run(async () =>
   619→        {
   620→            foreach (var group in highGroup)
   621→            {
   622→                await LoadGroup(group);
   623→                completedGroups++;
   624→                MainThreadDispatcher.ExecuteOnMainThread(() =>
   625→                    onProgress?.Invoke((float)completedGroups / totalGroups));
   626→            }
   627→
   628→            // 4. 空闲时加载普通资源
   629→            foreach (var group in normalGroup)
   630→            {
   631→                await LoadGroup(group);
   632→                completedGroups++;
   633→            }
   634→
   635→            // 5. 低优先级资源
   636→            foreach (var group in lowGroup)
   637→            {
   638→                await LoadGroup(group);
   639→                completedGroups++;
   640→            }
   641→        });
   642→    }
   643→
   644→    private async Task LoadGroup(PreloadGroup group)
   645→    {
   646→        var tasks = group.assetAddresses.Select(addr =>
   647→            Addressables.LoadAssetAsync<Object>(addr).Task);
   648→
   649→        await Task.WhenAll(tasks);
   650→    }
   651→}
   652→```
